    "etken_maddeler": [
      "Demir (Demir Bisglisinat Şelatı) 17 mg (%121 BRD)"
    ],
    "ne_ise_yarar": "Kırmızı kan hücreleri ve hemoglobinin normal oluşumuna, dokulara oksijen taşınmasına, hücresel enerji üretimine ve bağışıklık fonksiyonuna katkıda bulunur. Demir eksikliği anemisine bağlı kronik bitkinlik, saç dökülmesi, soluk ten ve sürekli üşüme şikayetlerini ortadan kaldırır.",
    "sgk_karsilastirmasi_ve_nis_bilgi": "💡 SGK (Devlet İlacı) vs. Eczane Şelatlı Demir Farkı:\n• Devlet İlaçları (Ferro Sanol Duodenal, Maltofer, Ferplex): İnorganik demir sülfat / demir hidroksit içerir. Mide asidinde serbest demir iyonu (Fe2+) açığa çıkarır; serbest demir mide mukozasını tahriş eder, reflü, mide krampı, metalik tat, siyah dışkı ve inatçı kabızlık yapar. Hastaların %50'si bu yan etkiler yüzünden tedaviyi yarıda bırakır.\n• Eczane Takviyesi (Solgar Gentle Iron): \"Demir Bisglisinat\" formundadır. Demir atomu 2 adet glisin amino asidi ile kıskaçlanmıştır (şelat). Mide asidinden etkilenmeden intakt (bütün) halde ince bağırsağa geçer ve aminoasit kanallarından emilir. Mideyi yakmaz, kabızlık yapmaz ve biyoyararlanımı klasik demir sülfata göre 4 kat daha yüksektir.",
    "kimler_icebilir": "12 yaşını doldurmuş ve 40 kg üzerindeki gençler, ferritin/demir düşüklüğü olan yetişkinler, gebeler (hekim önerisiyle), yoğun adet kanaması olan kadınlar, sporcular ve vejetaryenler/veganlar.",
    "ideal_kilo_araligi": "12+ Yaş ve Yetişkinler (40 kg üzeri)",
    "kimler_icemez": "🚨 ÇOK KRİTİK İLAÇ ETKİLEŞİMİ - GUATR / TİROİD İLAÇLARI (Levotiron, Euthyrox, Tefor):\nDemir, levotiroksin (tiroid hormonu) moleküllerine bağırsakta kuvvetle bağlanarak çözünmeyen şelat kompleksi oluşturur ve tiroid ilacının emilimini %90 oranında engeller. Tiroid ilacı kesinlikle sabah aç karna içilmeli; DEMİR HAPINI İSE MUTLAKA EN AZ 4 SAAT SONRA (öğlen veya akşam tok karna) almalıdır! Asla aynı saatte yutulmaz.\n\n⚠️ Diğer Kritik İlaç Etkileşimleri:\n• Mide Koruyucular (PPI - Lansor, Nexium, Pantpas, Rennie, Talcid): Mide asidini sıfırladığı için demir emilimini bozar; araya en az 2 saat konmalıdır.\n• Antibiyotikler (Florokinolonlar - Cipro, Avelox ve Tetrasiklinler): Demir ile çakışır, antibiyotiğin etkisini yok eder; en az 3 saat ara verilmelidir.\n• Çay, Kahve, Süt ve Yoğurt: İçerdikleri tanen ve kalsiyum demiri çöktürür; demir takviyesinden 2 saat önce ve sonra tüketilmemelidir (Tercihen C vitamini / taze portakal suyu ile alınmalıdır).\n• Hemokromatozis (demir depolama hastalığı) ve Talasemi (Akdeniz anemisi) olanlar hekim kontrolü olmadan kesinlikle içmemelidir.",
    "kimler_kullanamaz": "12 yaş altı çocuklar ve hemokromatozis hastaları kullanmamalıdır.",
